// Validate crafting request
const craftingRequest = $input.first().json.body;

// Basic validation
if (!craftingRequest.crafterId || !craftingRequest.recipeId || !craftingRequest.materials) {
  return [{ json: { error: 'Missing required fields: crafterId, recipeId, materials' } }];
}

// Check materials availability
const materialValidation = {
  valid: true,
  missing: [],
  insufficient: []
};

for (const material of craftingRequest.materials) {
  // This would integrate with inventory system
  const availableQuantity = await getMaterialQuantity(material.id, craftingRequest.crafterId);

  if (availableQuantity === 0) {
    materialValidation.valid = false;
    materialValidation.missing.push(material.id);
  } else if (availableQuantity < material.quantity) {
    materialValidation.valid = false;
    materialValidation.insufficient.push({
      id: material.id,
      required: material.quantity,
      available: availableQuantity
    });
  }
}

if (!materialValidation.valid) {
  return [{
    json: {
      error: 'Material validation failed',
      details: materialValidation
    }
  }];
}

// Validate crafter skill level
const crafter = await getCrafter(craftingRequest.crafterId);
const recipe = await getRecipe(craftingRequest.recipeId);

if (!crafter || !recipe) {
  return [{ json: { error: 'Invalid crafter or recipe' } }];
}

if (crafter.skills[recipe.profession] < recipe.requiredSkill) {
  return [{
    json: {
      error: 'Insufficient skill level',
      required: recipe.requiredSkill,
      current: crafter.skills[recipe.profession]
    }
  }];
}

// Calculate crafting parameters
const craftingParams = {
  successChance: calculateSuccessChance(crafter, recipe, craftingRequest.materials),
  qualityModifier: calculateQualityModifier(crafter, recipe, craftingRequest.materials),
  timeMultiplier: calculateTimeModifier(crafter, recipe),
  experienceGain: calculateExperienceGain(recipe, craftingRequest.options)
};

return [{
  json: {
    valid: true,
    craftingRequest: craftingRequest,
    crafter: crafter,
    recipe: recipe,
    params: craftingParams
  }
}];

