// Simulate crafting completion
const craftingData = $input.first().json;
const successRoll = Math.random();
const successChance = craftingData.params.successChance;

const isSuccessful = successRoll < successChance;
const isCriticalSuccess = successRoll < (successChance * 0.1);
const isCriticalFailure = successRoll > (successChance + 0.1);

let result = {
  crafterId: craftingData.craftingRequest.crafterId,
  recipeId: craftingData.craftingRequest.recipeId,
  timestamp: new Date().toISOString(),
  success: isSuccessful,
  criticalSuccess: isCriticalSuccess,
  criticalFailure: isCriticalFailure
};

if (isSuccessful) {
  // Calculate item quality
  const baseQuality = 50;
  const skillBonus = (craftingData.crafter.skills[craftingData.recipe.profession] / 100) * 20;
  const materialBonus = (craftingData.params.qualityModifier - 1) * 30;
  const criticalBonus = isCriticalSuccess ? 25 : 0;

  result.quality = Math.max(1, Math.min(100, Math.floor(
    baseQuality + skillBonus + materialBonus + criticalBonus + (Math.random() - 0.5) * 20
  )));

  // Generate item properties
  result.item = {
    id: generateItemId(),
    name: craftingData.recipe.name,
    type: craftingData.recipe.type,
    quality: result.quality,
    properties: generateItemProperties(craftingData.recipe, result.quality, isCriticalSuccess),
    durability: calculateDurability(craftingData.recipe, result.quality, isCriticalSuccess),
    value: calculateItemValue(craftingData.recipe, result.quality)
  };

  result.experience = Math.floor(craftingData.params.experienceGain * (isCriticalSuccess ? 2 : 1));
} else {
  result.failureType = isCriticalFailure ? 'critical' : 'normal';
  result.experience = Math.floor(craftingData.params.experienceGain * (isCriticalFailure ? 0.1 : 0.3));

  if (isCriticalFailure) {
    result.penalties = generateFailurePenalties(craftingData.recipe);
  }
}

// Update crafter statistics
await updateCrafterStats(craftingData.crafterId, result);

return [{ json: result }];

function generateItemId() {
  return 'item_' + Date.now().toString(36) + Math.random().toString(36).substr(2);
}

function generateItemProperties(recipe, quality, isCritical) {
  const properties = { ...recipe.baseProperties };

  if (quality >= 90) {
    properties.legendary = true;
    properties.bonusStats = { damage: Math.floor(quality * 1.5) };
  } else if (quality >= 75) {
    properties.epic = true;
    properties.bonusStats = { damage: Math.floor(quality * 1.25) };
  }

  if (isCritical) {
    properties.masterwork = true;
    properties.additionalSlots = 1;
  }

  return properties;
}

function calculateDurability(recipe, quality, isCritical) {
  const baseDurability = recipe.baseProperties?.durability || 100;
  const qualityMultiplier = quality / 100;
  const criticalBonus = isCritical ? 1.5 : 1;

  return Math.floor(baseDurability * qualityMultiplier * criticalBonus);
}

function calculateItemValue(recipe, quality) {
  const baseValue = recipe.value || 100;
  const qualityMultiplier = 1 + (quality - 50) / 50;

  return Math.floor(baseValue * qualityMultiplier);
}

function generateFailurePenalties(recipe) {
  return {
    materialLoss: 0.5,
    durabilityDamage: 25,
    experiencePenalty: 0.2
  };
}

