// Mass production branch
const productionRequest = $input.first().json.body;

if (!productionRequest.orderId || !productionRequest.items) {
  return [{ json: { error: 'Missing mass production parameters' } }];
}

// Get production order details
const productionOrder = await getProductionOrder(productionRequest.orderId);
if (!productionOrder) {
  return [{ json: { error: 'Invalid production order' } }];
}

// Calculate production requirements
const productionPlan = {
  orderId: productionRequest.orderId,
  items: productionRequest.items,
  totalQuantity: productionRequest.items.reduce((sum, item) => sum + item.quantity, 0),
  estimatedTime: calculateTotalProductionTime(productionOrder, productionRequest.items),
  requiredMaterials: calculateTotalMaterials(productionRequest.items),
  qualityAssurance: setupQualityAssurance(productionOrder),
  progressTracking: setupProgressTracking(productionOrder)
};

return [{ json: productionPlan }];

async function getProductionOrder(orderId) {
  // Integration with order management system
  return {
    id: orderId,
    clientId: 'client_123',
    items: [],
    deadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
  };
}

function calculateTotalProductionTime(order, items) {
  return items.reduce((total, item) => {
    return total + (item.craftingTime * item.quantity);
  }, 0);
}

function calculateTotalMaterials(items) {
  const materials = {};

  items.forEach(item => {
    item.materials?.forEach(material => {
      if (!materials[material.id]) {
        materials[material.id] = 0;
      }
      materials[material.id] += material.quantity * item.quantity;
    });
  });

  return materials;
}

function setupQualityAssurance(order) {
  return {
    sampleRate: 0.1,
    qualityThreshold: 70,
    inspectionPoints: ['mid_production', 'completion']
  };
}

function setupProgressTracking(order) {
  return {
    updateInterval: 300000, // 5 minutes
    milestones: generateMilestones(order.items)
  };
}

function generateMilestones(items) {
  return items.map((item, index) => ({
    id: `milestone_${index}`,
    item: item.name,
    targetQuantity: item.quantity,
    completed: 0
  }));
}

// Update production progress
const productionData = $input.first().json;
const currentTime = new Date().toISOString();

// Calculate progress for each item
const progress = productionData.items.map(item => {
  const itemProgress = Math.min(100, Math.floor(
    (Date.now() - productionData.startTime) / (item.estimatedTime / item.quantity) * 100
  ));

  return {
    itemId: item.id,
    itemName: item.name,
    targetQuantity: item.quantity,
    completedQuantity: Math.floor(item.quantity * itemProgress / 100),
    progressPercentage: itemProgress,
    estimatedCompletion: new Date(Date.now() + (item.estimatedTime * (100 - itemProgress) / 100)).toISOString()
  };
});

// Check quality assurance samples
const qualityResults = [];
if (productionData.qualityAssurance && Math.random() < productionData.qualityAssurance.sampleRate) {
  const sampleResult = performQualitySample(productionData);
  qualityResults.push(sampleResult);
}

// Update production status
const productionUpdate = {
  orderId: productionData.orderId,
  timestamp: currentTime,
  progress: progress,
  overallProgress: Math.floor(progress.reduce((sum, item) => sum + item.progressPercentage, 0) / progress.length),
  qualityAssurance: qualityResults,
  status: determineProductionStatus(progress)
};

// Send progress update
await sendProgressUpdate(productionUpdate);

// Check if production is complete
if (productionUpdate.overallProgress >= 100) {
  return [{ json: { ...productionUpdate, completed: true } }];
}

return [{ json: productionUpdate }];

function performQualitySample(productionData) {
  return {
    sampleId: generateSampleId(),
    timestamp: new Date().toISOString(),
    quality: Math.floor(70 + Math.random() * 30),
    defects: Math.random() < 0.1 ? generateDefects() : [],
    passed: Math.random() < 0.95
  };
}

function generateDefects() {
  const defectTypes = ['surface_imperfection', 'dimensional_error', 'material_flaw', 'assembly_error'];
  const numDefects = Math.floor(Math.random() * 3) + 1;

  return Array.from({ length: numDefects }, () => ({
    type: defectTypes[Math.floor(Math.random() * defectTypes.length)],
    severity: Math.random() < 0.3 ? 'major' : 'minor'
  }));
}

function determineProductionStatus(progress) {
  const overallProgress = progress.reduce((sum, item) => sum + item.progressPercentage, 0) / progress.length;

  if (overallProgress >= 100) return 'completed';
  if (overallProgress >= 75) return 'final_stages';
  if (overallProgress >= 50) return 'halfway';
  if (overallProgress >= 25) return 'underway';
  return 'started';
}

function generateSampleId() {
  return 'sample_' + Date.now().toString(36) + Math.random().toString(36).substr(2);
}

async function sendProgressUpdate(update) {
  // Integration with notification system
  console.log('Sending production progress update:', update.orderId);
}

// Handle guild workshop operations
const workshopRequest = $input.first().json.body;

switch (workshopRequest.operation) {
  case 'create':
    return handleWorkshopCreation(workshopRequest);
  case 'upgrade':
    return handleWorkshopUpgrade(workshopRequest);
  case 'craft':
    return handleGuildCrafting(workshopRequest);
  case 'manage':
    return handleWorkshopManagement(workshopRequest);
  default:
    return [{ json: { error: 'Invalid workshop operation' } }];
}

async function handleWorkshopCreation(request) {
  const workshop = {
    id: generateWorkshopId(),
    guildId: request.guildId,
    type: request.workshopType,
    level: 1,
    resources: request.initialResources || 1000,
    members: [request.creatorId],
    upgrades: [],
    bonuses: calculateWorkshopBonuses(request.workshopType, 1),
    createdAt: new Date().toISOString(),
    status: 'active'
  };

  // Save workshop to database
  await saveWorkshop(workshop);

  return [{ json: { success: true, workshop: workshop } }];
}

async function handleWorkshopUpgrade(request) {
  const workshop = await getWorkshop(request.workshopId);
  if (!workshop) {
    return [{ json: { error: 'Workshop not found' } }];
  }

  const upgradeCost = calculateUpgradeCost(workshop.level);
  if (workshop.resources < upgradeCost) {
    return [{ json: { error: 'Insufficient resources for upgrade' } }];
  }

  workshop.level += 1;
  workshop.resources -= upgradeCost;
  workshop.bonuses = calculateWorkshopBonuses(workshop.type, workshop.level);
  workshop.upgrades.push({
    type: 'level_upgrade',
    timestamp: new Date().toISOString(),
    cost: upgradeCost
  });

  await saveWorkshop(workshop);

  return [{ json: { success: true, workshop: workshop } }];
}

async function handleGuildCrafting(request) {
  const workshop = await getWorkshop(request.workshopId);
  if (!workshop) {
    return [{ json: { error: 'Workshop not found' } }];
  }

  // Apply workshop bonuses to crafting
  const enhancedRequest = {
    ...request.craftingRequest,
    workshopBonuses: workshop.bonuses
  };

  // Process crafting with bonuses
  const craftingResult = await processGuildCrafting(enhancedRequest);

  return [{ json: craftingResult }];
}

function calculateWorkshopBonuses(type, level) {
  const baseBonuses = {
    blacksmithing: { successChance: 0.1, quality: 1.1, speed: 1.2 },
    alchemy: { successChance: 0.15, potency: 1.2, duration: 1.3 },
    enchanting: { successChance: 0.12, power: 1.25, stability: 1.15 },
    tailoring: { successChance: 0.08, durability: 1.15, comfort: 1.2 }
  };

  const bonuses = baseBonuses[type] || baseBonuses.blacksmithing;
  const levelMultiplier = 1 + (level - 1) * 0.05;

  Object.keys(bonuses).forEach(key => {
    bonuses[key] *= levelMultiplier;
  });

  return bonuses;
}

function calculateUpgradeCost(currentLevel) {
  return Math.floor(1000 * Math.pow(1.5, currentLevel));
}

function generateWorkshopId() {
  return 'workshop_' + Date.now().toString(36) + Math.random().toString(36).substr(2);
}

